contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 value) public payable {
        uint256 cBefore = address(c).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 cAfter = address(c).balance;

        assert(
            (reverted && cAfter == cBefore) ||
            (!reverted && cAfter == cBefore - value)
        );
    }

    receive() external payable {}
}

